// Compare real Chromium screenshots with OWNER-APPROVED images only.
// Unapproved/missing baselines cannot turn a test red or become new baselines.
const fs = require('node:fs');
const path = require('node:path');
const {PNG} = require('pngjs');
const output = 'visual-captures';
const baselines = 'visual-baselines';
fs.mkdirSync(output, {recursive:true});
const images = fs.readdirSync(output).filter(f => f.endsWith('.png') && !f.startsWith('diff-')).sort();
const results = [];
let failures = 0;
for (const name of images) {
  const expected = path.join(baselines, name);
  const actual = path.join(output, name);
  if (!fs.existsSync(expected)) {
    results.push({image:name, status:'awaiting-approved-Figma-baseline'});
    continue;
  }
  try {
    const reference = PNG.sync.read(fs.readFileSync(expected));
    const rendered = PNG.sync.read(fs.readFileSync(actual));
    if (reference.width !== rendered.width || reference.height !== rendered.height) {
      results.push({image:name, status:'failed', reason:'dimensions', expected:[reference.width,reference.height], actual:[rendered.width,rendered.height]});
      failures++;
      continue;
    }
    const total = reference.width * reference.height;
    let different = 0;
    const overlay = new PNG({width:reference.width, height:reference.height});
    for (let i=0;i<total;i++) {
      const k=i*4;
      const delta=Math.max(...[0,1,2,3].map(channel=>Math.abs(reference.data[k+channel]-rendered.data[k+channel])));
      if (delta > 40) {
        different++;
        overlay.data[k]=255; overlay.data[k+1]=0; overlay.data[k+2]=40; overlay.data[k+3]=255;
      } else {
        overlay.data[k]=rendered.data[k]; overlay.data[k+1]=rendered.data[k+1]; overlay.data[k+2]=rendered.data[k+2]; overlay.data[k+3]=64;
      }
    }
    const ratio = different / total;
    const status = ratio > 0.05 ? 'failed' : 'passed';
    if (status==='failed') {
      failures++;
      fs.writeFileSync(path.join(output,'diff-'+name),PNG.sync.write(overlay));
    }
    results.push({image:name,status,differentPixels:different,totalPixels:total,differentRatio:Number(ratio.toFixed(6))});
  } catch (error) {
    results.push({image:name,status:'failed',reason:String(error.message)});
    failures++;
  }
}
if (!images.length) {
  results.push({status:'failed',reason:'No real screenshots were generated'});
  failures++;
}
const report={generatedAt:new Date().toISOString(), screenshots:images.length, approvedBaselines:results.filter(r=>r.status!=='awaiting-approved-Figma-baseline').length, failures, results};
fs.writeFileSync(path.join(output,'report.json'),JSON.stringify(report,null,2)+'\n');
const lines=[
  '# Work — visual correction handoff',
  'This report is generated by CI against the real rendered application. Do not treat pending baselines as failures.',
  'For each failed image, inspect the screenshot and diff in the GitHub Actions visual-captures artifact.',
  'Compare against the approved Figma image stored in visual-baselines/ with the same filename.',
  'Correct UI code only, retake the screenshot, and rerun this workflow. Never auto-approve or overwrite the baseline.',
  'Do not modify Supabase, auth, permissions, billing, payroll, or destructive business operations in a visual-only fix.',
  'GitHub Actions cannot launch or keep a ChatGPT Work session running; Work must be active to apply corrections.',
  '',
  '## Machine-readable results',
  JSON.stringify(report,null,2)
];
fs.writeFileSync(path.join(output,'WORK_VISUAL_FIX.md'),lines.join('\n')+'\n');
if (process.env.GITHUB_STEP_SUMMARY) {
  fs.appendFileSync(process.env.GITHUB_STEP_SUMMARY,[
    '### Visual comparison',
    'Screenshots: '+report.screenshots+'; approved references checked: '+report.approvedBaselines+'; failed: '+report.failures+'.',
    'Missing baselines are not auto-approved; screenshots and diff images are available in the artifact.',
    '',
    ...results.map(r=>'- '+(r.image||'capture')+': '+r.status+(r.differentRatio!==undefined?' ('+(r.differentRatio*100).toFixed(2)+'% changed)':'')),
    ''
  ].join('\n'));
}
console.log(JSON.stringify(report,null,2));
if (failures) process.exitCode=1;
